// REAL FRAMES FROM THE RIDER'S OWN PACK. DO NOT EDIT BY HAND.
//
// Copied verbatim from the raw-frame table of the 2026-09-02 backup of the
// pack "KevinJK" (JK-BD6A20S6P, 20S, hardware 20H, software 20.20), which
// speaks JK02_32S. The reference implementation's captures are all from a
// JK02_24S device, so until these landed the 32-cell framing was only ever
// exercised against frames the simulator built. That is how a rule that
// rejects the real pack survived: nothing real had ever been run through it.
//
// Timestamps are the phone's clock, UTC.
import 'dart:typed_data';

Uint8List _hex(String s) {
  final out = Uint8List(s.length ~/ 2);
  for (var i = 0; i < out.length; i++) {
    out[i] = int.parse(s.substring(i * 2, i * 2 + 2), radix: 16);
  }
  return out;
}

